"""Author the audit evidence registry, without promoting unverified subrules."""
import hashlib
import importlib.util
import json
from pathlib import Path
import sys

spec = importlib.util.spec_from_file_location('audit_rules', 'scripts/audit_rules.py')
mod = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = mod
spec.loader.exec_module(mod)
root = Path('docs/rules/audit-2026-10')
raw = Path('scratch/MagicCompRules-20260925.txt').read_bytes()
rules = mod.inventory(raw)
metadata = dict(schema_version=1, source_url='https://media.wizards.com/2026/downloads/MagicCompRules%2020260925.txt', discovery_url='https://magic.wizards.com/en/rules', effective_date='2026-09-25', retrieved_utc='2026-10-22', sha256=hashlib.sha256(raw).hexdigest(), audited_revision='20194feb758cd6d1df3e63b8d4fdd567d3ebbe6f', numbered_entries=len(rules), ordered_ids_sha256=hashlib.sha256('\n'.join(r.id for r in rules).encode()).hexdigest(), inventory_policy='Every numbered body chapter/section/rule/subrule, including multi-letter suffixes. TOC duplicates, examples, glossary and credits excluded. Source line numbers are one-based inclusive; per-entry digest normalizes LF and trims trailing whitespace. Parent digest covers its own paragraph, not descendants.')
(root/'source.json').write_text(json.dumps(metadata,indent=2)+'\n')
profiles = {}
families = {}
def profile(key, sections, scope, owners, evidence, gap, dispersion='dispersed'):
 profiles[key] = dict(scope=scope, inspected_owners=owners, evidence=evidence, gap=gap, ownership=dispersion, comments='Inspect individual entry before claiming comment adequacy.', anchors=[])
 for section in sections.split(): families[section] = key
